 const filtered=filterProducts(products,{query,occasion,flower,shade,category,maxPrice,minPrice,inStock,sort});
 const reloadAdmin=async()=>{setAdmin(await api('admin/data'));await load()};
 const repeat=(o:any)=>{let skipped=0;const additions:CartLine[]=[];for(const l of o.items){const p=products.find((p:any)=>p.id===l.productId);if(!p?.available||!p.sizes.find((s:any)=>s.name===l.size)){skipped++;continue}additions.push({productId:p.id,size:l.size,packaging:p.packaging.includes(l.packaging)?l.packaging:p.packaging[0],qty:Math.min(l.qty,20),addons:l.addons.map((a:any)=>a.id).filter((id:string)=>st.addons.some((a:any)=>a.id===id&&a.available))})}setCart(c=>[...c,...additions]);nav('/cart');notify('Добавлено по текущим ценам'+(skipped?'. Недоступных позиций: '+skipped:'. Проверьте сумму заказа.'))};
 const card=(p:any)=>{const s=p.sizes.find((x:any)=>x.name==='M')||p.sizes[0];return <article className="product" key={p.id}><div className="product-photo"><button className="image-button" onClick={()=>open(p)} aria-label={'Подробнее о букете '+p.name}><img src={p.image} alt={'Букет «'+p.name+'» — демонстрационная фотография'} loading="lazy"/></button><button className={'favorite '+(favs.includes(p.id)?'selected':'')} onClick={()=>favorite(p)} aria-label={favs.includes(p.id)?'Убрать из избранного':'В избранное'}><Heart size={19} fill={favs.includes(p.id)?'currentColor':'none'}/></button><span className="photo-label">{!p.available?'Нет в наличии':p.category==='Монобукеты'?'Монобукет':'Авторский букет'}</span></div><div className="product-heading"><button onClick={()=>open(p)} className="plain"><h3>{p.name}</h3></button><span>{price(s.price)}</span></div><p className="composition">{s.composition} · {s.name}</p><button className="add-button" disabled={!p.available} onClick={()=>add(p,s.name)}>{p.available?'Добавить в корзину':'Сейчас недоступен'}<Plus size={16}/></button></article>};
 if(error)return <main className="empty"><Flower2 size={48}/><h1>Магазин временно недоступен</h1><p>{error}</p><button onClick={()=>location.reload()}>Повторить</button></main>;
 if(!data)return <main className="empty"><Flower2 className="spin" size={40}/><p>Собираем для вас цветочную историю…</p></main>;
