 {adminTab==='orders'&&<><div className="order-filters"><div className="search"><Search size={17}/><input placeholder="Номер, имя или телефон" aria-label="Поиск заказов" value={orderSearch} onChange={e=>setOrderSearch(e.target.value)}/></div><select aria-label="Фильтр статуса" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="">Все статусы</option>{statuses.map(s=><option key={s}>{s}</option>)}</select><Field label="С"><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="По"><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field></div>{admin.orders.filter((o:any)=>(!statusFilter||o.status===statusFilter)&&(!from||o.created.slice(0,10)>=from)&&(!to||o.created.slice(0,10)<=to)&&(o.id+' '+o.buyer.name+' '+o.buyer.phone).toLowerCase().includes(orderSearch.toLowerCase())).map((o:any)=><details className="order-card" key={o.id}><summary className="row"><span><b>{o.id}</b> · {o.buyer.name}<small>{new Date(o.created).toLocaleString('ru-RU')} · {o.demo?'Демо':''}</small></span><span className="status">{o.status}</span><b>{price(o.total,o.currency)}</b></summary><div className="order-details"><div className="two-fields"><div><h4>Покупатель</h4><p>{o.buyer.name} · {o.buyer.phone}</p><p>{o.buyer.email||'Email не указан'}</p></div><div><h4>Получатель</h4><p>{o.recipient} · {o.recipientPhone}</p><p>{o.anonymous?'Анонимный подарок':'Обычный подарок'}</p></div></div><p><MapPin size={15}/> {o.address}</p><p>{o.method==='pickup'?'Самовывоз':'Доставка'} · {o.zone} · {o.date} · {o.interval}</p>{o.items.map((l:any,i:number)=><div className="order-line" key={i}><img src={l.image} alt={l.name}/><div><b>{l.name} · {l.size} · {l.qty} шт.</b><p>{l.composition}</p><small>{l.packaging} · {l.addons.map((a:any)=>a.name).join(', ')}</small></div><b>{price(l.lineTotal)}</b></div>)}<p>Текст открытки: {o.card||'—'}</p><p>Комментарий: {o.comment||'—'}</p><p>Товары и дополнения: {price(o.subtotal,o.currency)} · Скидка: {price(o.discount,o.currency)} {o.code} · Доставка: {price(o.delivery,o.currency)}</p><form className="order-status-form" onSubmit={e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));run(async()=>{await api('admin/orders/'+o.id,'PATCH',b);await reloadAdmin();notify('Статус обновлён в заказе покупателя')})}}><Field label="Статус заказа"><select name="status" defaultValue={o.status}>{statuses.map(s=><option key={s}>{s}</option>)}</select></Field><Field label="Статус оплаты"><select name="payment" defaultValue={o.payment}>{['Не оплачен','Оплачен (демо)','Возврат (демо)'].map(s=><option key={s}>{s}</option>)}</select></Field><button className="primary" disabled={busy}>Сохранить</button></form></div></details>)}</>}
